#!/usr/bin/env bash
# Reproduce S4 lumpi-track submission 's4' (model-lumpi-track/routed-g4): test-frame inference with the exact
# checkpoints, merge with the committed model.yaml, compare with the scored zip, repackage the same 50 frames, kit check.
# Generated by common/tools/reproduce_submission.py; scored zip model-lumpi-track/routed-g4/submissions/2026-10-10_s4/lumpi_s4_submission.zip (md5 ce3dc93c3f7defd7e0ca74bd0efc702a).
# Usage: CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g4/test/reproduce_s4.sh
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
OUT=model-lumpi-track/routed-g4/test/output/repro_s4
mkdir -p $OUT
# member cp_tta: model-lumpi-track/centerpoint-g1v3, checkpoint md5 25e4c0acf63d4b8f3b425fdc37bb3898
python common/tools/pcdet_predict.py model-lumpi-track/centerpoint-g1v3 --ckpt model-lumpi-track/centerpoint-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/centerpoint-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_cp_tta.json
# member g1: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess.yaml --out $OUT/predictions_g1.json
# member g1_tta: model-lumpi-track/pointpillars-g1, checkpoint md5 16e68b8b9142688967e4b3d006ac9d54
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1 --ckpt model-lumpi-track/pointpillars-g1/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1_tta.json
# member g1v3: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess.yaml --out $OUT/predictions_g1v3.json
# member g1v3_tta: model-lumpi-track/pointpillars-g1v3, checkpoint md5 e403acdc3ae30a84de3989da34619440
python common/tools/pcdet_predict.py model-lumpi-track/pointpillars-g1v3 --ckpt model-lumpi-track/pointpillars-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pointpillars-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_g1v3_tta.json
# member pv_tta: model-lumpi-track/pvrcnnpp-g1v3, checkpoint md5 fd25c22b76cf55863ca66a9ce28bc508
python common/tools/pcdet_predict.py model-lumpi-track/pvrcnnpp-g1v3 --ckpt model-lumpi-track/pvrcnnpp-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/pvrcnnpp-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_pv_tta.json
# member vr_tta: model-lumpi-track/voxelrcnn-g1v3, checkpoint md5 c2756955e8a260f0ff1573b232d71279
python common/tools/pcdet_predict.py model-lumpi-track/voxelrcnn-g1v3 --ckpt model-lumpi-track/voxelrcnn-g1v3/train/output/pcdet_model/run1/ckpt/checkpoint_epoch_40.pth --frames kit --postprocess model-lumpi-track/voxelrcnn-g1v3/test/postprocess_tta.yaml --tta flip4+yaw+z --out $OUT/predictions_vr_tta.json
python common/tools/route_predictions.py merge model-lumpi-track/routed-g4 --pred cp_tta=$OUT/predictions_cp_tta.json --pred g1=$OUT/predictions_g1.json --pred g1_tta=$OUT/predictions_g1_tta.json --pred g1v3=$OUT/predictions_g1v3.json --pred g1v3_tta=$OUT/predictions_g1v3_tta.json --pred pv_tta=$OUT/predictions_pv_tta.json --pred vr_tta=$OUT/predictions_vr_tta.json --out $OUT/predictions.json
python common/tools/reproduce_submission.py model-lumpi-track/routed-g4 --tag s4 --compare $OUT/predictions.json
# the 50 realism frames: from the synthetic corpus when it is present (a check that it still gives the scored frames),
# else from the scored zip itself (a fresh clone has no corpus; the zip is in git)
if [ -d "$BDC_DATA/lumpi-track/pcdet/g1-v2/points" ]; then SYN=(--syn-split val --syn-list model-lumpi-track/routed-g4/submissions/2026-10-10_s4/synthetic_ids.txt); else SYN=(--syn-zip model-lumpi-track/routed-g4/submissions/2026-10-10_s4/lumpi_s4_submission.zip --syn-list model-lumpi-track/routed-g4/submissions/2026-10-10_s4/synthetic_ids.txt); fi
python common/tools/package_submission.py model-lumpi-track/routed-g4 --tag repro-s4 --pred $OUT/predictions.json --synthetic pcdet/g1-v2 "${SYN[@]}" --team ${BDC_TEAM:-KarmaRV} --ckpt 'reproduction of s4' --reproduction
Z=model-lumpi-track/routed-g4/test/output/repro-s4/submission.zip
python common/tools/check_submission.py --track lumpi $Z --official
python common/tools/reproduce_submission.py model-lumpi-track/routed-g4 --tag s4 --compare-zip $Z     # predictions and frames against the scored zip
